fn is_prime(n: i8) -> bool {
    // Negative numbers, 0, and 1 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 up to n-1
    let mut divisor: i8 = 2;
    
    while divisor < n {
        // If n is divisible by divisor, it's not prime
        if n % divisor == 0 {
            return false;
        }
        divisor += 1;
    }
    
    // No divisors found, so n is prime
    true
}